"""SkyDiscover entry point for SimpleTES scaling_law/easy_question_scaling_law (generated by scripts/port_simpletes.py).

evaluator.py beside this file is the untouched upstream evaluator.  This stub runs it
through benchmarks/simpletes/skydiscover_adapter.py, which reproduces SimpleTES's
EvaluatorWorker: a fresh subprocess per candidate (cwd = TMPDIR = a throw-away dir,
PYTHONPATH = the suite root so `simpletes` and sitecustomize.py behave as upstream) with a
hard 3000 s kill in the role of SimpleTES's --eval-timeout (see EVAL_TIMEOUT in
scripts/port_simpletes.py for how the value was chosen; upstream's default is 3000 s).
"""
import sys
from pathlib import Path

_SUITE_ROOT = Path(__file__).resolve().parents[3]
if str(_SUITE_ROOT) not in sys.path:
    sys.path.insert(0, str(_SUITE_ROOT))

from skydiscover_adapter import make_evaluate  # noqa: E402

evaluate = make_evaluate(Path(__file__).with_name("evaluator.py"), timeout=3000)

from final_metrics import evaluate_scaling_final

def evaluate_final(program_path):
    """Fit on train and report held-out test R2 after evolution."""
    return evaluate_scaling_final(program_path, Path(__file__).with_name("evaluator.py"))
